// Product logos, shipped with the design system so every consumer app
// (cloud, turing, shio, dumont, …) references a single source of truth.
//
// The product marks are isometric cubes with the front-top corner cut in the
// angle of the Viglet V. They are generated by make_marks.py in the
// alegauss/visibility repository (marca/logo/), where the geometry is
// documented: copy them over after regenerating, never edit them by hand.
// Each product has two: the cube with its symbol (Tu, Sh, Du) for 56 px and
// up, and the cube alone for smaller sizes, where the symbol stops reading.
import vigletLogoUrl from "./viglet.svg";
import turingLogoUrl from "./turing.svg";
import shioLogoUrl from "./shio.svg";
import dumontLogoUrl from "./dumont.svg";
import turingSmallLogoUrl from "./turing-small.svg";
import shioSmallLogoUrl from "./shio-small.svg";
import dumontSmallLogoUrl from "./dumont-small.svg";

export {
  vigletLogoUrl,
  turingLogoUrl,
  shioLogoUrl,
  dumontLogoUrl,
  turingSmallLogoUrl,
  shioSmallLogoUrl,
  dumontSmallLogoUrl,
};

/**
 * Convenience map keyed by product id, matching the `vg-dot-*` utility
 * class names and the institutional palette.
 */
export const productLogos = {
  viglet: vigletLogoUrl,
  turing: turingLogoUrl,
  shio: shioLogoUrl,
  dumont: dumontLogoUrl,
} as const;

/** The same marks for sizes below 56 px: the cube without its symbol. */
export const productSmallLogos = {
  viglet: vigletLogoUrl,
  turing: turingSmallLogoUrl,
  shio: shioSmallLogoUrl,
  dumont: dumontSmallLogoUrl,
} as const;

export type ProductId = keyof typeof productLogos;
